-- Silent Artist: the aliases sit next to each word, so the 'silent-artist' edge function judges guesses from the
-- table (the same list as src/games/silent/data/words.json). Re-run with the new aliases when the word list changes.
alter table public.sa_words add column if not exists aliases text[] not null default '{}';
update public.sa_words s set aliases = array(select jsonb_array_elements_text(e->1))
